MainAPI:Slider({Title="Walk Speed", Flag="WalkSpeed", Min=SLIDER_MIN, Max=SLIDER_MAX, Step=1, Default=16, Suffix=" SPD", Callback=function(v) sliderSpeed=v local hum=plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if hum then hum.WalkSpeed=v hum:SetAttribute("BaseSpeed",v) end end})

MainAPI:Section("STEAL CONFIG")
MainAPI:Dropdown({Title="Rarity Filter", Flag="RarityFilter", Options=rarityNames, Multi=true, Callback=function(val) selected={} if type(val)=="table" then for _,n in ipairs(val) do selected[n]=true end elseif val then selected[val]=true end end})
MainAPI:Dropdown({Title="Zone Filter", Flag="ZoneFilter", Options=zoneNames, Multi=true, Callback=function(val) selectedZones={} if type(val)=="table" then for _,n in ipairs(val) do selectedZones[n]=true end elseif val then selectedZones[val]=true end end})
MainAPI:Dropdown({Title="Defend Mode", Flag="DefendMode", Options=defendModes, Default="None", Callback=function(val) defendMode=type(val)=="table" and val[1] or val defendMode=defendMode or "None" end})
MainAPI:Textbox({Title="Min $ /Sec", Flag="MinCash", Placeholder="$ 0 = off", Callback=function(text) local v=parseFilterInput(text) minCashFilter=v if v>0 then Window.Notify("FILTER $", "Min $"..tostring(v), ACCENT, 2) else Window.Notify("FILTER $", "OFF", DIM, 2) end end})

local function getStealTargets() local folder=workspace:FindFirstChild("AnimalPickups") if not folder or next(selected)==nil then return {} end local out={} for _,m in ipairs(folder:GetChildren()) do if m:IsA("Model") and selected[m:GetAttribute("Rarity")] then if next(selectedZones)~=nil then local z=getAnimalZone(m) if not selectedZones[z] then continue end end if minCashFilter>0 then local cash=parseCash(getCashPerSecond(m)) if cash<minCashFilter then continue end end table.insert(out,m) end end table.sort(out,function(a,b) return getRarityScore(a:GetAttribute("Rarity") or "")>getRarityScore(b:GetAttribute("Rarity") or "") end) return out end

MainAPI:Toggle({Title="Auto Steal", Flag="AutoSteal", Default=false, Callback=function(v)
    if v then
        if next(selected)==nil then Window.Notify("ERROR", "Pilih Rarity dulu!", Color3.fromRGB(248,113,113), 3) return end
        walkToSafeBase()
        task.spawn(function()
            while getgenv().SORU_AutoSteal do
                local list=getStealTargets()
                local found=#list>0
                for _,m in ipairs(list) do if not getgenv().SORU_AutoSteal then break end pcall(function() stealMethod(m) end) task.wait(0.5) end
                if not found then task.wait(0.8) end
            end
        end)
    end
    getgenv().SORU_AutoSteal=v
end})

MainAPI:Toggle({Title="Attack Carrier", Flag="AttackCarrier", Default=false, Callback=function(v) attackEnabled=v Window.Notify("ATTACK", v and "ON" or "OFF", v and Color3.fromRGB(255,80,80) or DIM, 2) end})

MainAPI:Section("BREAK EGG")
MainAPI:Dropdown({Title="Egg Zone", Flag="EggZone", Options=zoneNames, Callback=function(val) selectedEggZone=type(val)=="table" and val[1] or val end})
MainAPI:Toggle({Title="Big Egg Priority", Flag="BigEggPrio", Default=true, Callback=function(v) bigEggPriority=v Window.Notify("BIG EGG", v and "Biggest First" or "OFF", v and ACCENT or DIM, 2) end})

local function getEggSize(model) for _,a in ipairs({"Size","EggSize","Scale","WeightKg","Weight","SizeMultiplier"}) do local v=model:GetAttribute(a) if typeof(v)=="number" then return v end end for _,d in ipairs(model:GetDescendants()) do if d:IsA("NumberValue") and d.Name:lower():find("size") then return d.Value end end local ok,_,sz=pcall(function() return model:GetBoundingBox() end) if ok and sz then return sz.Magnitude end return 0 end
local function getEggsInZone(zoneName) local zb=getZoneBuildsFolder() if not zb then return {} end local zoneModel=zb:FindFirstChild(zoneName) if not zoneModel then return {} end local eggsRoot=zoneModel:FindFirstChild("Eggs") or zoneModel local out={} for _,v in ipairs(eggsRoot:GetChildren()) do if v:IsA("Model") and v.Name:lower():find("egg") then table.insert(out,v) end end if #out==0 then for _,v in ipairs(eggsRoot:GetDescendants()) do if v:IsA("Model") and v.Name:lower():find("egg") then table.insert(out,v) end end end if bigEggPriority then table.sort(out,function(a,b) return getEggSize(a)>getEggSize(b) end) end return out end
local function getEggHealth(eggModel) if eggModel:GetAttribute("Health") then return eggModel:GetAttribute("Health") end for _,d in ipairs(eggModel:GetDescendants()) do local h=d:GetAttribute("Health") if h~=nil then return h end end return nil end
local function equipPickaxe() local char=plr.Character if not char then return nil end local tool=char:FindFirstChildOfClass("Tool") if tool and tool.Name:lower():find("pickaxe") then return tool end for _,t in ipairs(plr.Backpack:GetChildren()) do if t:IsA("Tool") and t.Name:lower():find("pickaxe") then t.Parent=char return t end end for _,t in ipairs(plr.Backpack:GetChildren()) do if t:IsA("Tool") then t.Parent=char return t end end return char:FindFirstChildOfClass("Tool") end

MainAPI:Toggle({Title="Break Egg", Flag="BreakEgg", Default=false, Callback=function(v)
    if v then
        if not selectedEggZone then Window.Notify("ERROR", "Pilih Zone dulu!", Color3.fromRGB(248,113,113), 2) return end
        task.spawn(function()
            while getgenv().SORU_BreakEgg do
                local targets=getStealTargets()
                if #targets>0 then for _,m in ipairs(targets) do if not getgenv().SORU_BreakEgg then break end pcall(function() stealMethod(m) end) task.wait(0.3) end continue end
                local eggs=getEggsInZone(selectedEggZone) if #eggs==0 then task.wait(1) continue end
                for _,egg in ipairs(eggs) do
                    if not getgenv().SORU_BreakEgg then break end
                    if #getStealTargets()>0 then break end
                    local pos,base=getOffsetPos(egg) if not pos then local b=getBasePos(egg) if b then pos=Vector3.new(b.X,3.5,b.Z+3) base=Vector3.new(b.X,3.5,b.Z) end end
                    if not pos then continue end
                    pcall(function() walkDirect(pos,base,false) equipPickaxe() while getgenv().SORU_BreakEgg and egg.Parent do if #getStealTargets()>0 then break end local h=getEggHealth(egg) if h==nil or h<=0 then break end task.wait(0.15) end end)
                    task.wait(0.2)
                end
                task.wait(0.5)
            end
        end)
    end
    getgenv().SORU_BreakEgg=v
end})

