MainAPI:Dropdown({Title="Player List", Flag="PlayerList", Options=getPlayerList(), Callback=function(val) local name=type(val)=="table" and val[1] or val if name and name~="No Player" then selectedFollowPlayer=name Window.Notify("FOLLOW", "Target "..name, ACCENT, 2) end end})
