    else
        Window.Notify("FOLLOW", "OFF", DIM, 2)
    end
end})

MiscAPI:Section("MISC UTILITY")
local noRagdollOn=false local ragdollConns={}
local function enableNoRagdoll() for _,c in ipairs(ragdollConns) do pcall(function() c:Disconnect() end) end ragdollConns={} local char=plr.Character local hum=char and char:FindFirstChildOfClass("Humanoid") if hum then pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll,false) hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown,false) hum.BreakJointsOnDeath=false hum.PlatformStand=false end) table.insert(ragdollConns,hum.StateChanged:Connect(function(_,new) if new==Enum.HumanoidStateType.Ragdoll or new==Enum.HumanoidStateType.FallingDown then hum:ChangeState(Enum.HumanoidStateType.GettingUp) end end)) end table.insert(ragdollConns,RunService.Heartbeat:Connect(function() local c=plr.Character local h=c and c:FindFirstChildOfClass("Humanoid") if h then if h:GetState()==Enum.HumanoidStateType.Ragdoll or h:GetState()==Enum.HumanoidStateType.FallingDown then h:ChangeState(Enum.HumanoidStateType.GettingUp) h.PlatformStand=false end h:SetStateEnabled(Enum.HumanoidStateType.Ragdoll,false) h:SetStateEnabled(Enum.HumanoidStateType.FallingDown,false) end end)) end
local function disableNoRagdoll() for _,c in ipairs(ragdollConns) do pcall(function() c:Disconnect() end) end ragdollConns={} local hum=plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if hum then pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll,true) hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown,true) hum.BreakJointsOnDeath=true end) end end
MiscAPI:Toggle({Title="No Ragdoll", Flag="NoRagdoll", Default=false, Callback=function(v) noRagdollOn=v if v then enableNoRagdoll() else disableNoRagdoll() end end})

local antiMentalOn=false local antiMentalConns={}
local function enableAntiMental() for _,c in ipairs(antiMentalConns) do pcall(function() c:Disconnect() end) end antiMentalConns={} table.insert(antiMentalConns,RunService.Heartbeat:Connect(function() local char=plr.Character local hrp=char and char:FindFirstChild("HumanoidRootPart") if not hrp then return end local vel=hrp.AssemblyLinearVelocity local flat=Vector3.new(vel.X,0,vel.Z).Magnitude if flat>35 then hrp.AssemblyLinearVelocity=Vector3.new(0,vel.Y,0) hrp.AssemblyAngularVelocity=Vector3.zero pcall(function() hrp.Velocity=Vector3.new(0,hrp.Velocity.Y,0) end) end if hrp.AssemblyAngularVelocity.Magnitude>20 then hrp.AssemblyAngularVelocity=Vector3.zero end end)) end
local function disableAntiMental() for _,c in ipairs(antiMentalConns) do pcall(function() c:Disconnect() end) end antiMentalConns={} end
MiscAPI:Toggle({Title="Anti Mental", Flag="AntiMental", Default=false, Callback=function(v) antiMentalOn=v if v then enableAntiMental() else disableAntiMental() end end})

MiscAPI:Section("GAMEPASS")
local fastBreakOn=false local fastBreakConn=nil
local function setFastBreakAttribute(state) pcall(function() plr:SetAttribute("FastSwingOwned",state) end) pcall(function() if plr.Character then plr.Character:SetAttribute("FastSwingOwned",state) end end) end
MiscAPI:Toggle({Title="Fast Break", Flag="FastBreak", Default=false, Callback=function(v) fastBreakOn=v if fastBreakOn then setFastBreakAttribute(true) if fastBreakConn then fastBreakConn:Disconnect() end fastBreakConn=RunService.Heartbeat:Connect(function() if plr:GetAttribute("FastSwingOwned")~=true then setFastBreakAttribute(true) end end) else if fastBreakConn then fastBreakConn:Disconnect() fastBreakConn=nil end setFastBreakAttribute(false) end end})

EspAPI:Section("ESP SYSTEM")
EspAPI:Dropdown({Title="Rarity Filter ESP", Flag="EspRarity", Options=rarityNames, Multi=true, Callback=function(val) selectedEspRarity={} if type(val)=="table" then for _,n in ipairs(val) do selectedEspRarity[n]=true end elseif val then selectedEspRarity[val]=true end if espEnabled then refreshAllEsp() end end})
EspAPI:Toggle({Title="Animal ESP", Flag="AnimalESP", Default=false, Callback=function(v) espEnabled=v if espEnabled then refreshAllEsp() Window.Notify("ESP", "ON", ACCENT, 2) task.spawn(function() while espEnabled do refreshAllEsp() task.wait(1.5) end end) local folder=workspace:FindFirstChild("AnimalPickups") if folder then folder.ChildAdded:Connect(function(m) if espEnabled and m:IsA("Model") then task.wait(0.2) createAnimalEsp(m) end end) folder.ChildRemoved:Connect(function(m) removeAnimalEsp(m) end) end else clearAllEsp() Window.Notify("ESP", "OFF", DIM, 2) end end})
local clearOnRespawn=true
EspAPI:Toggle({Title="Clear ESP On Death", Flag="ClearEsp", Default=true, Callback=function(v) clearOnRespawn=v end})

PlotAPI:Section("PLOT")
PlotAPI:Toggle({Title="Equip Best", Flag="EquipBest", Default=false, Callback=function(v)
    if v then
        task.spawn(function()
            while getgenv().SORU_EquipBest do
                pcall(function() RS.PetsInventoryRemote:FireServer("EquipBest", nil) end)
                task.wait(1.5)
            end
        end)
    end
    getgenv().SORU_EquipBest=v
end})

PlotAPI:Section("INDEX")
PlotAPI:Toggle({Title="Auto Claim Index", Flag="ClaimIndex", Default=false, Callback=function(v)
    if v then
        task.spawn(function()
            while getgenv().SORU_ClaimIndex do
                pcall(function() RS.IndexRemote:FireServer("ClaimAll", nil) end)
                task.wait(2)
            end
        end)
    end
    getgenv().SORU_ClaimIndex=v
end})

BlatantAPI:Section("INSTANT STEAL")
BlatantAPI:Button({Title="Instant Steal", Callback=function()
    local folder=workspace:FindFirstChild("AnimalPickups") if not folder then Window.Notify("BLATANT", "No Animals", DIM, 2) return end
    local best=nil local bestCash=0
    for _,m in ipairs(folder:GetChildren()) do if m:IsA("Model") then local c=parseCash(getCashPerSecond(m)) if c>bestCash then bestCash=c best=m end end end
    if not best then Window.Notify("BLATANT", "No Target", DIM, 2) return end
    Window.Notify("BLATANT", best.Name.." $"..bestCash, ACCENT, 2)
    local hrp=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not hrp then return end
    local pos=getOffsetPos(best) if not pos then pos=getBasePos(best) end
    if pos then hrp.CFrame=CFrame.new(pos) task.wait(0.08) for i=1,3 do fireSteal(best) touchSteal(best) pressE() task.wait(0.05) end task.wait(0.15) hrp.CFrame=CFrame.new(SAFE_BASE_POS) end
end})

plr.CharacterAdded:Connect(function(char) task.wait(0.5) local hum=char:WaitForChild("Humanoid",15) if hum then local realSpeed=hum.WalkSpeed sliderSpeed=realSpeed hum:SetAttribute("BaseSpeed",realSpeed) end task.wait(0.5) if noRagdollOn then enableNoRagdoll() end if antiMentalOn then enableAntiMental() end if fastBreakOn then setFastBreakAttribute(true) end if clearOnRespawn then clearAllEsp() end if espEnabled then task.wait(0.5) refreshAllEsp() end end)
RunService.Heartbeat:Connect(function() local hum=plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if hum then if math.abs(hum.WalkSpeed-sliderSpeed)>0.1 then hum.WalkSpeed=sliderSpeed end end end)
